-- Derive display bounds with the project's assembler. Resolving the complete
-- source also handles mapping aliases, shared frames and inline mapping tables.
local bounds = {}
local generated_path = "_definitions/Sprite Bounds.asm"
local pass_rom = "sprite-bounds-pass.bin"
local pass_listing = "sprite-bounds-pass.lst"
local header = [[; ---------------------------------------------------------------------------
; Generated by build.lua through build_tools/lua/sprite_bounds.lua.
; Half-bounds cover every piece of every frame, including flips.
; Change the mappings or object initializer; the build regenerates these values.
; ---------------------------------------------------------------------------
sprite_bound function limit,maplimit,limit+((maplimit-limit)*(limit<maplimit))

]]

local function read_file(path)
	local file = io.open(path, "rb")
	if not file then return nil end
	local text = file:read("a")
	file:close()
	return text
end

local function write_file(path, text)
	local file = assert(io.open(path, "wb"), "Cannot write " .. path)
	file:write(text)
	file:close()
end

local function word(data, offset)
	assert(offset >= 0 and offset + 2 <= #data, "Mapping runs beyond its data")
	return string.unpack(">I2", data, offset + 1)
end

local function signed_word(data, offset)
	local value = word(data, offset)
	return value >= 0x8000 and value - 0x10000 or value
end

-- Binary exports can place frame zero after other frames. The earliest frame
-- offset delimits the pointer table; the first offset alone need not do so.
local function binary_frame_count(data)
	local boundary, offset = #data, 0
	while offset < boundary do
		local target = signed_word(data, offset)
		assert(target > 0 and target % 2 == 0, "Invalid binary mapping frame offset")
		boundary = math.min(boundary, target)
		offset = offset + 2
		assert(offset <= boundary and offset <= 512, "Cannot delimit mapping frame table")
	end
	return offset // 2
end

local function discover()
	local references, seen, asm_counts, binary_counts = {}, {}, {}, {}
	local function visit(path)
		if seen[path] or path == generated_path then return end
		seen[path] = true
		local text = read_file(path)
		-- Inactive conditional includes need not exist; the assembler diagnoses
		-- any missing include that is actually used by the selected build.
		if not text then return end
		local current_label
		for line in text:gmatch("[^\r\n]+") do
			local code = line:match("^[^;]*")
			for label in code:gmatch("(Map[%w_]*_height)") do references[label] = true end
			for label in code:gmatch("(Map[%w_]*_width)") do references[label] = true end
			for label in code:gmatch("(Map[%w_]*_frames)") do references[label] = true end
			local label = code:match("^%s*([%w_%.]+):")
			if label then current_label = label end
			local words = code:match("%f[%w_]dc%.w%s+(.+)")
			if words then
				for base in words:gmatch("[%w_%.]+%s*%-%s*(Map[%w_]*)") do
					asm_counts[base] = (asm_counts[base] or 0) + 1
				end
			end
			local binary = code:match('%f[%w_]binclude%s+"([^"\n]+)"')
			if binary and current_label then
				binary_counts[current_label] = binary
			end
			local include = code:match('%f[%w_]include%s+"([^"\n]+%.asm)"')
			if include then visit(include) end
		end
	end
	visit("main.asm")
	local maps = {}
	for reference in pairs(references) do
		maps[reference:gsub("_height$", ""):gsub("_width$", ""):gsub("_frames$", "")] = true
	end
	local labels = {}
	for label in pairs(maps) do labels[#labels + 1] = label end
	table.sort(labels)
	return labels, asm_counts, binary_counts
end

local function constants(labels, values)
	local lines = {header}
	for _, label in ipairs(labels) do
		local value = values[label] or {0, 0, 0}
		lines[#lines + 1] = string.format("%s_width = $%02X\n%s_height = $%02X\n%s_frames = %d\n",
			label, value[1], label, value[2], label, value[3])
	end
	return table.concat(lines)
end

local function mapping_bounds(image, address, frames)
	local width, height = 0, 0
	assert(frames > 0 and frames <= 256, "Invalid number of mapping frames")
	for frame = 0, frames - 1 do
		local position = address + signed_word(image, address + frame * 2)
		local pieces = word(image, position)
		assert(pieces < 0x8000, "Invalid S3&K piece count")
		for piece = 0, pieces - 1 do
			local offset = position + 2 + piece * 6
			local y, size = string.unpack("bI1", image, offset + 1)
			assert(size < 16, "Invalid S3&K sprite size")
			local x = signed_word(image, offset + 4)
			width = math.max(width, math.abs(x), math.abs(x + ((size >> 2) + 1) * 8))
			height = math.max(height, math.abs(y), math.abs(y + ((size & 3) + 1) * 8))
		end
	end
	assert(width <= 255 and height <= 255, "Mapping exceeds the byte-sized display bounds")
	return {width, height, frames}
end

function bounds.generate(common, as_arguments, p2bin_arguments, repository)
	local previous = read_file(generated_path)
	local success, result = pcall(function()
		local labels, asm_counts, binary_counts = discover()
		assert(#labels > 0, "No mapping bounds referenced by the source")
		-- Stub values break the dependency between object setup and mappings.
		-- This intermediate image is never used as the playable ROM.
		write_file(generated_path, constants(labels, {}))
		os.remove(pass_rom)
		os.remove(pass_listing)
		local message, abort = common.assemble_file("main.asm", pass_rom,
			as_arguments .. " -OLIST " .. pass_listing, p2bin_arguments, false, repository)
		assert(not abort, "Mapping assembly pass failed")
		local image = assert(read_file(pass_rom), "Mapping assembly produced no ROM")
		local listing = assert(read_file(pass_listing), "Mapping assembly produced no listing")
		local symbols, used = {}, {}
		for unused, name, value in listing:gmatch("(%*?)([%w_%.]+)%s*:%s*([%x]+)%s+[C%-]") do
			symbols[name] = tonumber(value, 16)
			used[name] = unused ~= "*"
		end
		local frames_by_address = {}
		local active_addresses = {}
		for _, label in ipairs(labels) do
			if used[label .. "_height"] or used[label .. "_width"] or used[label .. "_frames"] then
				active_addresses[assert(symbols[label], "No mapping table named " .. label)] = true
			end
		end
		for label, count in pairs(asm_counts) do
			if symbols[label] then frames_by_address[symbols[label]] = count end
		end
		for label, path in pairs(binary_counts) do
			if symbols[label] and active_addresses[symbols[label]] then
				frames_by_address[symbols[label]] = binary_frame_count(assert(read_file(path), path))
			end
		end
		local values, active, frames = {}, 0, 0
		for _, label in ipairs(labels) do
			if used[label .. "_height"] or used[label .. "_width"] or used[label .. "_frames"] then
				local address = assert(symbols[label], "No mapping table named " .. label)
				local count = assert(frames_by_address[address], "Cannot find frame table for " .. label)
				local ok, value = pcall(mapping_bounds, image, address, count)
				assert(ok, label .. ": " .. tostring(value))
				values[label] = value
				active, frames = active + 1, frames + count
			end
		end
		write_file(generated_path, constants(labels, values))
		print(string.format("Generated %d mapping bounds across %d frames.", active, frames))
		return true
	end)
	os.remove(pass_rom)
	os.remove(pass_listing)
	if not success then
		if previous then write_file(generated_path, previous) else os.remove(generated_path) end
		print("Sprite bounds generation failed: " .. tostring(result))
		return false
	end
	return result
end

return bounds
